# ============================================================
# DATABASE CLOUD — SUPABASE POSTGRESQL
# ============================================================

def get_conn():
    # Supabase fornisce una PostgreSQL connection string.
    # sslmode=require è necessario per una connessione cloud sicura.
    return psycopg2.connect(DATABASE_URL, sslmode="require")


def _sql(query: str) -> str:
    """Converte i placeholder SQLite ? nei placeholder PostgreSQL %s."""
    return query.replace("?", "%s")


def init_db():
    conn = get_conn()
    try:
        cur = conn.cursor()

        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS players (
                id BIGSERIAL PRIMARY KEY,
                activision_id TEXT UNIQUE NOT NULL,
                platform TEXT NOT NULL,
                selection TEXT DEFAULT 'Non Assegnato',
                status TEXT DEFAULT 'Pending',
                created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
                password_hash TEXT
            )
            """
        )

        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS submissions (
                id BIGSERIAL PRIMARY KEY,
                activision_id TEXT NOT NULL,
                kills INTEGER NOT NULL,
                wins INTEGER NOT NULL,
                rating_gained DOUBLE PRECISION NOT NULL,
                photo_path TEXT NOT NULL,
                month_year TEXT NOT NULL,
                status TEXT DEFAULT 'Pending',
                timestamp TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
                matches_played INTEGER
            )
            """
        )

        # Migrazioni non distruttive per tabelle eventualmente già create.
        cur.execute("ALTER TABLE players ADD COLUMN IF NOT EXISTS password_hash TEXT")
        cur.execute("ALTER TABLE submissions ADD COLUMN IF NOT EXISTS matches_played INTEGER")

        conn.commit()
    finally:
        conn.close()


def db_query(query, params=(), fetchall=False, commit=False):
    conn = get_conn()
    try:
        cur = conn.cursor()
        cur.execute(_sql(query), params)
        data = cur.fetchall() if fetchall else None
        if commit:
            conn.commit()
        return data
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


init_db()


# ============================================================
# SECURITY / HELPERS
# ============================================================

def hash_password(password: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 200_000)
    return f"{salt.hex()}:{digest.hex()}"


def verify_password(password: str, stored: str) -> bool:
    if not stored or ":" not in stored:
        return False
    try:
        salt_hex, digest_hex = stored.split(":", 1)
        digest = hashlib.pbkdf2_hmac(
            "sha256", password.encode(), bytes.fromhex(salt_hex), 200_000
        )
        return hmac.compare_digest(digest.hex(), digest_hex)
    except (ValueError, TypeError):
        return False


def calculate_rating(kills: int, wins: int) -> float:
    return kills * 10 + wins * 150


def safe_id(value: str) -> str:
    return re.sub(r"[^a-zA-Z0-9_-]", "_", value)


def save_proof(uploaded_file, activision_id: str) -> str:
    """Carica lo screenshot su Supabase Storage e restituisce il suo URL pubblico."""
    ext = os.path.splitext(uploaded_file.name)[1].lower()
    if ext not in {".png", ".jpg", ".jpeg", ".webp"}:
        raise ValueError("Formato immagine non supportato.")

    object_name = (
        f"{safe_id(activision_id)}/"
        f"{datetime.now().strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex}{ext}"
    )

    upload_url = (
        f"{SUPABASE_URL}/storage/v1/object/"
        f"{SUPABASE_BUCKET}/{object_name}"
    )

    headers = {
        "Authorization": f"Bearer {SUPABASE_SERVICE_KEY}",
        "apikey": SUPABASE_SERVICE_KEY,
        "Content-Type": uploaded_file.type or "application/octet-stream",
        "x-upsert": "false",
    }

    response = requests.post(
        upload_url,
        headers=headers,
        data=uploaded_file.getvalue(),
        timeout=45,
    )
    response.raise_for_status()

    # Il bucket viene configurato come pubblico nella guida inclusa.
    return (
        f"{SUPABASE_URL}/storage/v1/object/public/"
        f"{SUPABASE_BUCKET}/{object_name}"
    )


def medal(i):
    return ["🥇", "🥈", "🥉"][i] if i < 3 else str(i + 1)


def badge(status):
    return {
        "Approved": "✅ Approvato",
        "Pending": "⏳ In attesa",
        "Rejected": "❌ Rifiutato",
    }.get(status, status)


def get_player(activision_id):
    rows = db_query(
        """
        SELECT id, activision_id, platform, selection, status, created_at, password_hash
        FROM players WHERE activision_id=?
        """,
        (activision_id,),
        fetchall=True,
    ) or []
    return rows[0] if rows else None


